NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Zephaniah'

CHAPTERS = {
    1: {
        1: 'Herran sana, joka tuli Sefanjalle, Kuusin pojalle, joka oli Gedaljan poika, joka Amarjan poika, joka Hiskian poika, Juudan kuninkaan Joosian, Aamonin pojan, päivinä.',
        2: 'Totisesti otan pois maan pinnalta kaiken. Tämä on Herran sana.',
        3: 'Otan pois ihmiset ja eläimet, otan pois taivaan linnut ja meren kalat, viettelykset ja jumalattomat. Minä hävitän ihmiset maan pinnalta. Tämä on Herran sana.',
        4: 'Ojennan käteni Juudaa vastaan ja kaikkia Jerusalemin asukkaita vastaan, ja hävitän tästä paikasta Baalin jätteet, epäjumalien pappien nimet sekä myös papit,',
        5: 'ne, jotka katoilla kumartaen rukoilevat taivaan joukkoa, sekä ne, jotka kumartaen rukoilevat Herraa ja vannovat hänen kauttaan, mutta myös vannovat Melekinsä kautta,',
        6: 'sekä ne, jotka ovat luopuneet seuraamasta Herraa, eivät kysy Herraa eivätkä etsi häntä.',
        7: 'Vaiti Herran, Herran edessä! Sillä Herran päivä on lähellä; sillä Herra on valmistanut teurasuhrin ja pyhittänyt kutsuttunsa.',
        8: 'Mutta Herran teurasuhrin päivänä rankaisen päämiehiä ja kuninkaan poikia ja kaikkia muukalaisten pukuun puettuja.',
        9: 'Rankaisen sinä päivänä kaikkia kynnyksen yli hyppiviä, jotka täyttävät Herransa huoneen väkivallalla ja petoksella.',
        10: 'Tapahtuu sinä päivänä, sanoo Herra, että kuuluu huuto Kalaportilta ja valitus toiselta portilta ja suuri hävitys kukkuloilta.',
        11: 'Valittakaa, te Maktesin asukkaat, sillä tuhottu on kaikki kauppaa käyvä väki ja hävitetty kaikki hopean punnitsijat.',
        12: 'Tapahtuu siihen aikaan, että tutkin lampuilla Jerusalemin ja rankaisen niitä miehiä, jotka istuvat viinisakkansa päällä ja sanovat sydämessään: " Herra ei tee hyvää eikä pahaa."',
        13: 'Tapahtuu myös, että heidän rikkautensa joutuu ryöstettäväksi, ja heidän talonsa jäävät autioiksi. He ovat rakentaneet taloja, mutta eivät tule niissä asumaan. He ovat istuttaneet viinitarhoja, mutta eivät tule juomaan niiden viiniä.',
        14: 'Lähellä on Herran suuri päivä. Se on lähellä ja tulee hyvin nopeasti. Kuule, Herran päivä! Silloin sankari huutaa katkerasti.',
        15: 'Vihan päivä on se päivä, tuskan ja ahdistuksen päivä, tuhon ja hävityksen päivä, pimeyden ja synkeyden päivä, pilven ja mustien pilvien päivä,',
        16: 'sotatorven ja sotahuudon päivä luoksepääsemättömiä kaupunkeja ja korkeita muurinkulmia vastaan.',
        17: 'Minä saatan ihmiset ahdistukseen, niin että he kulkevat kuin sokeat, sillä he ovat tehneet syntiä Herraa vastaan. Heidän verensä vuodatetaan kuin tomu, ja heidän elinnesteensä kuin uloste.',
        18: 'Heidän hopeansa ja kultansa eivät voi pelastaa heitä Herran vihan päivänä. Hänen kiivautensa tulessa kuluu koko maa. Sillä lopun, äkkilopun, hän tekee kaikista maan asukkaista.',
    },
    2: {
        1: 'Kokoontukaa, tulkaa yhteen, te häpeämätön kansa,',
        2: 'ennen kuin määräys on toteutettu – päivä kiitää pois kuin akana – ennen kuin teidän päällenne tulee Herran vihan hehku, ennen kuin teidän päällenne tulee Herran vihan päivä.',
        3: 'Etsikää Herraa, kaikki maan nöyrät, te, jotka noudatatte hänen oikeuttaan. Etsikää vanhurskautta, etsikää nöyryyttä. Ehkä te saatte suojan Herran vihan päivänä.',
        4: 'Sillä Gassa on oleva hylätty ja Askelon autio, Asdod ajetaan pois keskipäivällä, ja Ekron hävitetään.',
        5: 'Voi meren rannikon asukkaita, kreettien kansaa! Herran sana on sinua vastaan, Kanaan, filistealaisten maa. Minä hävitän sinut, niin ettei sinussa ole asukkaita.',
        6: 'Meren rannikko on oleva laitumina, joilla on paimenten majoja ja lammastarhoja.',
        7: 'Rannikko on oleva Juudan heimon jäännöksen hallussa. Siellä he laiduntavat. Askelonin taloihin he asettuvat makaamaan illoin. Sillä Herra, heidän Jumalansa, on pitävä heistä huolen ja kääntävä heidän kohtalonsa.',
        8: 'Olen kuullut Mooabin ivat ja ammonilaisten pilkat, joilla he ovat häpäisseet kansaani ja ylvästelleet sen aluetta vastaan.',
        9: 'Sen tähden, niin totta kuin minä elän, – tämä on Herran Sebaotin, Israelin Jumalan, sana – Mooab on tuleva Sodoman kaltaiseksi ja ammonilaiset Gomorran kaltaisiksi, nokkosmaaksi, suolakuopaksi, autioksi iankaikkisesti. Kansani jäännös ryöstää heitä, ja kansakuntani jäljelle jääneet ottavat heidät perintöosakseen.',
        10: 'Tämä tulee heille heidän ylpeytensä tähden, sillä he ovat herjanneet ja ylvästelleet Herran Sebaotin kansaa vastaan.',
        11: 'Pelottava on Herra heille oleva, sillä hän tekee voimattomiksi kaikki maan jumalat; ja kaikki pakanoiden saaret kukin paikallaan tulevat häntä kumartaen rukoilemaan.',
        12: 'Teidätkin, kuusilaiset, on miekkani kaatava!',
        13: 'Hän on ojentava kätensä pohjoista kohden, hukuttava Assurin ja tekevä Niiniven autioksi, kuivaksi kuin erämaa.',
        14: 'Sen keskellä makaa laumoja, kaikkia kansojen petoeläimiä. Pöllö ja siili yöpyvät sen patsaiden seassa. Kuule, kuinka ne laulavat ikkuna-aukossa! Kynnyksellä on tyhjyys. Setrilaudoituksen hän on paljastanut.',
        15: 'Tämä oli se riemuitseva kaupunki, joka asui turvallisena ja sanoi sydämessään: "Minä, eikä ketään muuta!" Kuinka autioksi se on tullut, villieläinten makuusijaksi! Jokainen, joka käy siitä ohi, viheltää ja heiluttaa kättään.',
    },
    3: {
        1: 'Voi uppiniskaista, saastaista ja väkivaltaista kaupunkia!',
        2: 'Se ei ole totellut ääntä, ei huolinut ojennuksesta, ei luottanut Herraan eikä lähestynyt Jumalaansa.',
        3: 'Ruhtinaat sen keskellä ovat ärjyviä leijonia. Sen tuomarit ovat kuin sudet illalla, jotka eivät säästä aamua varten.',
        4: 'Sen profeetat ovat huikentelijoita, uskottomia miehiä. Sen papit saastuttavat pyhän ja tekevät väkivaltaa laille.',
        5: 'Herra on vanhurskas sen keskellä, hän ei tee vääryyttä. Joka aamu hän tuo valoon oikeutensa, se ei jää tulematta. Mutta väärintekijä ei tunne häpeää.',
        6: 'Olen hävittänyt pakanakansat, niiden muurinkulmat ovat autioina. Olen tehnyt niiden kadut raunioiksi eikä niillä ole kulkijoita. Niiden kaupungit ovat hävitetyt, niin ettei niissä ole ihmisiä eikä niissä asuta.',
        7: 'Olen sanonut: Pelkää ainoastaan minua ja ota varteen ojennus, niin tytär Siionin asumusta ei hävitetä eikä mitään siitä, mitä olen sille säätänyt. Kuitenkin he nousivat varhain turmellakseen kaikki tekonsa.',
        8: 'Sen tähden odottakaa minua – tämä on Herran sana – odottakaa sitä päivää, jona nousen saaliille. Sillä tuomiopäätökseni on, että kokoan pakanakansat ja saatan koolle valtakunnat vuodattaakseni heidän päälleen ankaruuteni ja vihani koko hehkun, sillä kiivauteni tuli kuluttaa koko maan',
        9: 'Silloin annan kansoille puhdistetut huulet, niin että ne kaikki huutavat avuksi Herran nimeä ja palvelevat häntä yhdessä.',
        10: 'Kuusin virtojen tuolta puolen rukoilijani – hajalla oleva tyttäreni kantaa minulle lahjoja.',
        11: 'Sinä päivänä sinä et enää häpeä mitään niistä teoistasi, joilla olet rikkonut minua vastaan, sillä silloin minä poistan keskuudestasi ylpeilijäsi, ne, jotka korottavat itsensä. Sitten et enää ylpeile pyhän vuoreni tähden.',
        12: 'Mutta minä jätän jäljelle keskuuteesi kurjan ja köyhän kansan, ne, jotka panevat turvansa Herran nimeen.',
        13: 'Israelin jäännökset eivät tee vääryyttä eivätkä puhu valhetta, eikä heidän suussaan tavata valheellista kieltä. Sillä ne ovat laitumella ja makaavat kenenkään pelottelematta.',
        14: 'Iloitse, tytär Siion, puhkea huutoon, Israel; ihastu ja riemuitse kaikesta sydämestäsi, tytär Jerusalem.',
        15: 'Herra on poistanut tuomiosi, kääntänyt pois vihollisesi. Israelin kuningas, Herra, on keskelläsi. Et tule enää näkemään onnettomuutta.',
        16: 'Sinä päivänä sanotaan Jerusalemille: "Älä pelkää, Siion, älkööt kätesi väsykö.',
        17: 'Herra, Jumalasi, asuu sinussa; hän on sankari, joka auttaa. Hän iloitsee sinusta ilolla, hän on ääneti, sillä hän rakastaa sinua, hän riemuitsee sinusta riemulla."',
        18: 'Minä kokoan ne, jotka ovat murheellisia juhlakokousten tähden. Hehän ovat olleet erossa sinusta. Häväistys on taakkana heidän päällään.',
        19: 'Katso, siihen aikaan teen tekoni kaikille nöyryyttäjillesi. Pelastan ontuvat ja kokoan karkotetut ja teen heidät ylistetyiksi ja kiitetyiksi jokaisessa maassa, jossa he olivat häpeän alaisina.',
        20: 'Siihen aikaan minä tuon teidät takaisin – siihen aikaan, jona teidät kokoan. Sillä teen teidät ylistetyiksi ja kiitetyiksi kaikissa maan kansoissa, kun käännän kohtalonne silmienne nähden, sanoo Herra.',
    },
}
